// Validate input and prepare for processing
const items = $input.all();
const output = [];

for (const item of items) {
  const chatInput = item.json.chatInput || item.json.product || '';
  const product = chatInput.trim();

  if (!product) {
    throw new Error('Product name is required. Please provide a valid product name.');
  }

  output.push({
    json: {
      product: product,
      productEncoded: encodeURIComponent(product),
      timestamp: new Date().toISOString()
    }
  });
}

return output;

// Parse Amazon response and extract price
const items = $input.all();
const output = [];

for (const item of items) {
  let result = {
    site: 'Amazon',
    currency: 'INR',
    price: null,
    status: 'error',
    productSearched: item.json.product || 'Unknown'
  };

  try {
    // Check if request failed
    if (item.error) {
      result.status = 'error';
      result.error_message = item.error.message || 'API request failed';
      output.push({ json: result });
      continue;
    }

    const html = item.json.data || item.json;

    if (!html || typeof html !== 'string') {
      result.status = 'parse_error';
      result.error_message = 'Invalid HTML response';
      output.push({ json: result });
      continue;
    }

    // Multiple price patterns for Amazon India
    const pricePatterns = [
      /<span class="a-price-whole">([\d,]+)<\/span>/,
      /"priceAmount":([\d.]+)/,
      /<span class="a-price">.*?₹([\d,]+)/,
      /data-a-color="price">.*?₹([\d,]+)/
    ];

    let priceFound = false;
    for (const pattern of pricePatterns) {
      const match = html.match(pattern);
      if (match && match[1]) {
        const priceStr = match[1].replace(/,/g, '');
        const price = parseFloat(priceStr);

        if (!isNaN(price) && price > 0) {
          result.price = Math.round(price);
          result.status = 'success';
          priceFound = true;
          break;
        }
      }
    }

    if (!priceFound) {
      result.status = 'not_found';
      result.error_message = 'Product or price not found on Amazon';
    }

  } catch (error) {
    result.status = 'parse_error';
    result.error_message = error.message;
  }

  output.push({ json: result });
}

return output;

// Parse Flipkart response and extract price
const items = $input.all();
const output = [];

for (const item of items) {
  let result = {
    site: 'Flipkart',
    currency: 'INR',
    price: null,
    status: 'error',
    productSearched: item.json.product || 'Unknown'
  };

  try {
    // Check if request failed
    if (item.error) {
      result.status = 'error';
      result.error_message = item.error.message || 'API request failed';
      output.push({ json: result });
      continue;
    }

    const html = item.json.data || item.json;

    if (!html || typeof html !== 'string') {
      result.status = 'parse_error';
      result.error_message = 'Invalid HTML response';
      output.push({ json: result });
      continue;
    }

    // Multiple price patterns for Flipkart
    const pricePatterns = [
      /<div class="[^"]*_30jeq3[^"]*">₹([\d,]+)<\/div>/,
      /"price":"₹([\d,]+)"/,
      /<div class="_25b18c">₹([\d,]+)<\/div>/,
      /₹([\d,]+)<\/div>/,
      /"amount":(\d+)/
    ];

    let priceFound = false;
    for (const pattern of pricePatterns) {
      const match = html.match(pattern);
      if (match && match[1]) {
        const priceStr = match[1].replace(/,/g, '');
        const price = parseFloat(priceStr);

        if (!isNaN(price) && price > 0) {
          result.price = Math.round(price);
          result.status = 'success';
          priceFound = true;
          break;
        }
      }
    }

    if (!priceFound) {
      result.status = 'not_found';
      result.error_message = 'Product or price not found on Flipkart';
    }

  } catch (error) {
    result.status = 'parse_error';
    result.error_message = error.message;
  }

  output.push({ json: result });
}

return output;

// Format final output with consolidated results
const items = $input.all();
const results = [];
let productName = 'Unknown';

for (const item of items) {
  if (item.json.site) {
    results.push({
      site: item.json.site,
      price: item.json.price,
      currency: item.json.currency || 'INR',
      status: item.json.status,
      ...(item.json.error_message && { error_message: item.json.error_message })
    });

    if (item.json.productSearched) {
      productName = item.json.productSearched;
    }
  }
}

const sourcesQueried = results.length;
const sourcesSucceeded = results.filter(r => r.status === 'success').length;

const output = {
  product: productName,
  results: results,
  sources_queried: sourcesQueried,
  sources_succeeded: sourcesSucceeded,
  timestamp: new Date().toISOString()
};

// Add summary message
if (sourcesSucceeded === 0) {
  output.message = 'No prices found. All sources failed or product not found.';
} else if (sourcesSucceeded < sourcesQueried) {
  output.message = `Partial results: ${sourcesSucceeded} out of ${sourcesQueried} sources returned prices.`;
} else {
  output.message = 'Successfully retrieved prices from all sources.';
}

return [{ json: output }];
